import {PLAN_KINDS as KINDS,UNIT_KINDS as UNITS,PLAN_TERMS as TERMS,COST_FIELDS as COSTS,CHANNELS,blankPlan,calculatePlan} from './pricing-model.js';
import {technicalUsageCard} from './usage-ui.js';
export function createPricingUI({api,esc,getState,getBoot,openDialog,closeDialog,toast}){
  let active=false,data=null,org='',sequence=0,pending=false;
  const money=n=>n===null||n===undefined?'A informar':new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n/100);
  const percent=n=>n===null||n===undefined?'—':new Intl.NumberFormat('pt-BR',{maximumFractionDigits:2}).format(n/100)+'%';
  const value=(v,type)=>v===null||v===undefined?'':['money','percent'].includes(type)?v/100:v;
  const area=(name,label,v='',required=false)=>`<label class="p-field"><span>${esc(label)}</span><textarea name="${name}" rows="3" maxlength="5000" ${required?'required':''}>${esc(v)}</textarea></label>`;
  const number=(name,label,v,type='number')=>`<label class="p-field"><span>${esc(label)}</span><input type="number" name="${name}" min="0" step="${type==='integer'?'1':'0.01'}" value="${esc(value(v,type))}" inputmode="decimal"></label>`;
  const text=(name,label,v='',type='text',max=1000)=>`<label class="p-field"><span>${esc(label)}</span><input name="${name}" type="${type}" value="${esc(v)}" maxlength="${max}"></label>`;
  const button=(label,action,id='',primary=false)=>`<button type="button" class="p-button ${primary?'primary':'secondary'}" data-pricing="${action}" data-id="${esc(id)}">${esc(label)}</button>`;
  const check=(name,label)=>`<label class="assisted-check"><input type="checkbox" name="${name}" required><span>${esc(label)}</span></label>`;
  const error='<p class="form-error" role="alert" hidden></p>';
  function simulation(plan){const result=calculatePlan(plan),c=result.selected;return `<div class="pricing-simulation"><p class="overline">SIMULAÇÃO · ${plan.kind==='subscription'?'POR MÊS':'POR PEDIDO'}</p><p>São projeções baseadas nos valores informados, não uma fatura ou garantia de resultado.</p><div class="pricing-metrics">${[['Custo antes dos percentuais',c?.baseCents],['Preço para a margem desejada',c?.minimumCents],['Preço de equilíbrio',c?.breakEvenCents],['Resultado no preço normal',c?.regular?.profitCents]].map(([k,v])=>`<div><span>${k}</span><strong>${money(v)}</strong></div>`).join('')}</div>${c?.complete?`<p>Margem normal: <strong>${percent(c.regular?.marginBps)}</strong> · capacidade estimada: <strong>${c.capacity??'não calculada'}</strong> clientes/pedidos por mês.</p><p>Trabalho por cliente/pedido: ${c.minutesPerCustomer.toLocaleString('pt-BR',{maximumFractionDigits:1})} minutos, com reserva de retrabalho e conciliação.</p><p>Resultado mensal projetado no volume informado: ${money(c.forecastProfitCents)}. As horas disponíveis devem ser exclusivas desta oferta, descontando as demais atividades.</p>${c.launch?`<p>Primeira mensalidade: ${money(c.launch.priceCents)} · resultado projetado ${money(c.launch.profitCents)} · margem ${percent(c.launch.marginBps)}. Depois: ${money(plan.regularPriceCents)} por mês.</p>`:''}<details><summary>Como o custo foi formado</summary><dl class="pricing-breakdown">${[['Custos diretos',c.directCents],['Trabalho humano',c.humanCents],['Rateio de custos fixos',c.overheadCents],['Reserva de retrabalho',c.reserveCents],['Tempo de conciliação',c.collectionCents],['Tarifa fixa de pagamento',c.paymentFixedCents]].map(([k,v])=>`<dt>${k}</dt><dd>${money(v)}</dd>`).join('')}</dl><p class="micro-copy">Preço para margem = custo antes dos percentuais ÷ (1 − tarifa percentual − tributos − margem desejada). Não conte infraestrutura ou trabalho duas vezes.</p></details>`:''}<h3>Comparar recebimento</h3><div class="pricing-channel-results">${result.channels.map(r=>`<article><h4>${CHANNELS[r.id]}</h4>${r.complete?`<p>Preço para a margem: <strong>${money(r.minimumCents)}</strong></p><p>Resultado no preço normal: ${money(r.regular?.profitCents)} · ${percent(r.regular?.marginBps)}</p>`:`<p>Faltam premissas para calcular.</p><p class="micro-copy">${esc(r.pending.join(' '))}</p>`}</article>`).join('')}</div><p role="status">${result.ready?'Ficha preenchida. Revise as premissas antes de usar em propostas.':result.issues.length+' pendência(s) antes da revisão.'}</p>${result.issues.length?`<details><summary>Ver pendências</summary><ul>${result.issues.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>`:''}${result.warnings.length?`<aside class="pricing-notice"><ul>${result.warnings.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></aside>`:''}</div>`;}
  function lineFields(l){return `<article class="pricing-line" data-pricing-line><div class="pricing-fields"><label class="p-field"><span>Entrega ou item de custo</span><select data-line="unit">${Object.entries(UNITS).map(([k,v])=>`<option value="${k}" ${l.unit===k?'selected':''}>${v}</option>`).join('')}</select></label><label class="p-field"><span>Quantidade por mês/pedido</span><input data-line="quantity" type="number" min="0" step="0.01" value="${esc(l.quantity??'')}"></label><label class="p-field"><span>Especificação para o cliente</span><input data-line="specification" maxlength="500" value="${esc(l.specification)}"></label><label class="p-field"><span>Custo direto por unidade válida (R$)</span><input data-line="unitCostCents" type="number" step="0.01" min="0" value="${esc(value(l.unitCostCents,'money'))}"></label><label class="p-field"><span>Minutos de trabalho por unidade</span><input data-line="minutes" type="number" step="0.01" min="0" value="${esc(l.minutes??'')}"></label><label class="p-field"><span>Origem do custo</span><select data-line="confidence">${[['unknown','Ainda não medido'],['estimate','Estimativa identificada'],['measured','Medido em amostra real']].map(([k,v])=>`<option value="${k}" ${l.confidence===k?'selected':''}>${v}</option>`).join('')}</select></label></div><label class="p-field"><span>Fonte, amostra e premissas do custo</span><textarea data-line="reference" rows="2" maxlength="1000">${esc(l.reference)}</textarea></label>${button('Remover item','remove-line')}</article>`;}
  const num=(v,type='number')=>{if(v===null||v===undefined||String(v).trim()==='')return null;const n=Number(v);return ['money','percent'].includes(type)?Math.round(n*100):n;};
  function readPlan(f){const values=Object.fromEntries(new FormData(f));return {kind:values.kind,name:values.name,terms:Object.fromEntries(TERMS.map(([k])=>[k,values['term_'+k]||''])),lines:[...f.querySelectorAll('[data-pricing-line]')].map(el=>Object.fromEntries(['unit','quantity','specification','unitCostCents','minutes','confidence','reference'].map(k=>{const v=el.querySelector('[data-line="'+k+'"]').value;return[k,['quantity','minutes','unitCostCents'].includes(k)?num(v,k==='unitCostCents'?'money':'number'):v];}))),costs:Object.fromEntries(COSTS.map(([k,,type])=>[k,num(values[k],type)])),costReference:values.costReference,observedDate:values.observedDate,channels:Object.keys(CHANNELS).map(id=>({id,percentBps:num(values[id+'_percent'],'percent'),fixedCents:num(values[id+'_fixed'],'money'),minutes:num(values[id+'_minutes']),reference:values[id+'_reference']})),selectedChannel:values.selectedChannel,regularPriceCents:num(values.regularPrice,'money'),launchPriceCents:num(values.launchPrice,'money'),launchSlots:num(values.launchSlots),launchUntil:values.launchUntil,launchConditions:values.launchConditions};}
  function recalculate(f){const host=f.querySelector('[data-pricing-simulation]');if(host)host.innerHTML=simulation(readPlan(f));}
  function edit(r){const p=r?.draft||blankPlan();openDialog(r?'Editar ficha da oferta':'Estruturar oferta',`<form data-pricing-form="save" data-id="${esc(r?.id||'')}" data-version="${r?.version||0}" data-key="${crypto.randomUUID()}"><p>Preencha o que já sabe e salve o rascunho. Campo vazio significa custo desconhecido. Informe zero somente quando o custo realmente for zero.</p><div class="pricing-fields"><label class="p-field"><span>Tipo da oferta</span><select name="kind">${Object.entries(KINDS).map(([k,v])=>`<option value="${k}" ${p.kind===k?'selected':''}>${v}</option>`).join('')}</select></label>${text('name','Nome da oferta',p.name,'text',120)}</div><details open><summary>1. Franquia, custos diretos e trabalho</summary><p>Conte entregas válidas, não chamadas de IA. Inclua custo de tentativas e falhas na média por entrega, sem duplicar esse valor na reserva de retrabalho. Inclua conversas, armazenamento, entrega e suporte quando gerarem custo.</p><div data-pricing-lines>${p.lines.map(lineFields).join('')}</div>${button('Adicionar entrega ou custo','add-line')}</details><details open><summary>2. Premissas e capacidade mensal</summary><div class="pricing-fields">${COSTS.map(([k,label,type])=>number(k,label,p.costs[k],type)).join('')}</div>${area('costReference','Fonte das premissas, câmbio quando aplicável e horas reservadas',p.costReference)}${text('observedDate','Data da conferência',p.observedDate,'date')}<p class="micro-copy">No avulso, a previsão mensal é o número de pedidos desta oferta. Nos custos fixos, informe somente a parcela destinada a ela. Desconte trabalho já incluído no custo por unidade.</p></details><details><summary>3. Stripe e boleto manual</summary><p>Use tarifas reais do seu contrato e a data/fonte da conferência. Estas informações não conectam nem alteram a cobrança.</p>${Object.entries(CHANNELS).map(([id,name])=>{const c=p.channels.find(x=>x.id===id);return `<fieldset><legend>${name}</legend><div class="pricing-fields">${number(id+'_percent','Tarifa percentual (%)',c?.percentBps,'percent')}${number(id+'_fixed','Tarifa fixa por recebimento (R$)',c?.fixedCents,'money')}${number(id+'_minutes','Minutos de conferência por recebimento',c?.minutes)}</div>${text(id+'_reference','Fonte e data da tarifa',c?.reference||'')}</fieldset>`;}).join('')}<label class="p-field"><span>Meio considerado para esta oferta</span><select name="selectedChannel">${Object.entries(CHANNELS).map(([id,name])=>`<option value="${id}" ${p.selectedChannel===id?'selected':''}>${name}</option>`).join('')}</select></label></details><details><summary>4. Ficha completa do que o cliente recebe</summary>${TERMS.map(([k,label])=>area('term_'+k,label,p.terms[k])).join('')}<p>A gestão de impulsionamento deve separar sua remuneração da verba de anúncios. Excedentes exigem autorização; não há cobrança variável automática.</p></details><details open><summary>5. Preço em avaliação</summary>${number('regularPrice',p.kind==='subscription'?'Preço normal mensal (R$)':'Preço por pedido (R$)',p.regularPriceCents,'money')}<details><summary>Simular primeira mensalidade com desconto</summary><p>Somente para o plano principal. A renovação usa o preço normal. Não há cupom ou cobrança ativados aqui.</p>${number('launchPrice','Primeira mensalidade (R$)',p.launchPriceCents,'money')}${number('launchSlots','Vagas reais reservadas ao lançamento',p.launchSlots,'integer')}${text('launchUntil','Validade da condição de lançamento',p.launchUntil,'date')}${area('launchConditions','Elegibilidade e condições do lançamento',p.launchConditions)}<p class="micro-copy">Para remover o desconto, deixe a primeira mensalidade em branco.</p></details></details><div data-pricing-simulation>${simulation(p)}</div>${error}<button class="p-button primary">Salvar rascunho</button></form>`,true);}
  function detail(r){const p=r.draft;openDialog(p.name||'Ficha da oferta',`<div class="pricing-detail"><p class="overline">${esc(KINDS[p.kind])} · versão ${r.revision} · ${r.state==='reviewed'?'Revisada internamente':r.state==='archived'?'Arquivada':'Rascunho'}</p><p>Esta ficha não é um plano ativo e não muda os limites dos clientes.</p>${simulation(p)}<details><summary>Franquia e condições para o cliente</summary><ul>${p.lines.map(l=>`<li>${esc(l.quantity??'A definir')} × ${esc(UNITS[l.unit])} — ${esc(l.specification)}</li>`).join('')}</ul>${TERMS.map(([k,label])=>`<h4>${label}</h4><p class="pricing-text">${esc(p.terms[k]||'A definir')}</p>`).join('')}</details><div class="assisted-actions">${button('Editar ficha','edit',r.id)}${r.state==='draft'?button('Revisar para propostas','review',r.id,true):''}${r.state!=='archived'?button('Arquivar oferta','archive',r.id):''}</div><details><summary>Histórico das revisões</summary>${r.versions.map(v=>`<details><summary>Versão ${v.number} · ${esc(new Date(v.at).toLocaleDateString('pt-BR'))} · ${money(v.plan.regularPriceCents)}</summary><p>${esc(v.plan.name)}</p>${simulation(v.plan)}${TERMS.map(([k,label])=>`<h4>${label}</h4><p class="pricing-text">${esc(v.plan.terms[k])}</p>`).join('')}</details>`).join('')||'<p>Ainda não há uma versão revisada.</p>'}</details></div>`,true);}
  function paint(){const root=document.querySelector('#pricing-workspace');if(!active||!root)return;if(!data){root.innerHTML='<p>Carregando fichas…</p>';return;}root.innerHTML=`<aside class="pricing-notice"><strong>Planejamento interno, sem cobrança ativada.</strong><p>Comece por um plano principal de criação e organize os opcionais separadamente. Custos, tarifas e preços vazios não são tratados como zero. Nenhum valor antigo foi adotado.</p></aside><div class="assisted-toolbar">${button('Estruturar oferta','new','',true)}${button('Atualizar fichas','refresh')}</div><div class="pricing-grid">${data.plans.map(r=>`<article class="panel pricing-card"><p class="overline">${esc(KINDS[r.draft.kind])} · ${r.state==='reviewed'?'Revisada internamente':r.state==='archived'?'Arquivada':'Rascunho'}</p><h2>${esc(r.draft.name||'Oferta em preparação')}</h2><p>Preço em avaliação: <strong>${money(r.draft.regularPriceCents)}</strong></p><p>${r.calculation.ready?'Ficha preenchida.':r.calculation.issues.length+' pendência(s) para revisar.'}</p>${button('Abrir ficha','detail',r.id)}</article>`).join('')||'<section class="panel pricing-card"><h2>Primeiro a entrega. Depois o preço.</h2><p>Crie a primeira ficha para comparar custo, capacidade e condições antes de preparar uma proposta comercial.</p></section>'}</div><details class="panel pricing-card"><summary>Consumo técnico registrado na empresa selecionada</summary>${technicalUsageCard(data.technicalUsage,esc)}<p>Para obter custo por entrega, concilie os valores pagos aos fornecedores e o tempo de trabalho com uma amostra de entregas válidas. Estes tokens não informam a fatura em reais.</p></details><section class="panel pricing-card"><h2>O que pode consumir serviços de IA</h2><p>Pedidos ao Astra, planejamento, geração de imagens e revisões feitas pela IA podem chamar os fornecedores. Renderização, armazenamento e entrega também podem ter custos próprios.</p><p>Navegar nesta área, preencher fichas, calcular cenários, revisar uma proposta e confirmar um aceite não iniciam uma geração. Créditos comerciais, quando existirem, precisam corresponder a entregas; chamadas internas não são uma franquia compreensível para o cliente.</p><a class="p-button secondary" href="#/commercial">Preparar proposta comercial</a></section>`;}
  async function load(){const ticket=++sequence,company=org;try{const result=await api('/api/portal/pricing?orgId='+encodeURIComponent(company));if(active&&ticket===sequence&&org===company){data=result;paint();}}catch(error){if(active&&ticket===sequence)document.querySelector('#pricing-workspace').innerHTML=`<p role="alert">${esc(error.message)}</p>${button('Tentar novamente','refresh')}`;}}
  document.addEventListener('click',e=>{const b=e.target.closest('[data-pricing]');if(!active||!b||pending)return;const a=b.dataset.pricing,r=data?.plans.find(x=>x.id===b.dataset.id),f=b.closest('[data-pricing-form]');if(a==='new')edit();else if(a==='refresh')load();else if(a==='add-line'&&f){if(f.querySelectorAll('[data-pricing-line]').length>=20){toast('Use até 20 itens por oferta.',true);return;}f.querySelector('[data-pricing-lines]').insertAdjacentHTML('beforeend',lineFields(blankPlan().lines[0]));recalculate(f);}else if(a==='remove-line'&&f){if(f.querySelectorAll('[data-pricing-line]').length===1){toast('Mantenha pelo menos um item.',true);return;}b.closest('[data-pricing-line]').remove();recalculate(f);}else if(r){if(a==='edit')edit(r);else if(a==='detail')detail(r);else if(['review','archive'].includes(a))openDialog(a==='review'?'Revisar oferta para propostas':'Arquivar oferta',`<form data-pricing-form="${a}" data-id="${esc(r.id)}" data-version="${r.version}">${a==='review'?simulation(r.draft)+check('confirmed','Conferi fontes, custos, tarifas, tributos, escopo e condições. Estimativas estão identificadas. Custos de IA, tentativas, armazenamento, entrega e suporte estão contemplados sem duplicação.')+check('capacityConfirmed','As horas e vagas informadas estão reservadas a esta oferta, descontando outras atividades. Entendo que revisar não publica preço, cria cupom ou ativa cobrança.'):'<p>A oferta deixará de aparecer como base para novas propostas. Propostas já enviadas preservam suas condições.</p>'}${error}<button class="p-button primary">Confirmar</button></form>`,true);}});
  for(const event of ['input','change'])document.addEventListener(event,e=>{if(!active)return;const f=e.target.closest('[data-pricing-form=save]');if(f)recalculate(f);});
  document.addEventListener('submit',async e=>{const f=e.target.closest('[data-pricing-form]');if(!active||!f)return;e.preventDefault();if(pending)return;const fd=new FormData(f),action=f.dataset.pricingForm,input={action,id:f.dataset.id||undefined,version:Number(f.dataset.version),requestKey:f.dataset.key,orgId:org,confirmed:fd.get('confirmed')==='on',capacityConfirmed:fd.get('capacityConfirmed')==='on'};if(action==='save')input.plan=readPlan(f);pending=true;const button=f.querySelector('button:not([type])'),company=org;button.disabled=true;try{const result=await api('/api/portal/pricing','POST',input);if(active&&company===org){closeDialog();await load();toast('Ficha registrada. Nenhuma cobrança foi ativada.');if(action==='save')detail(result);}}catch(error){const el=f.querySelector('[role=alert]');el.textContent=error.message;el.hidden=false;}finally{pending=false;button.disabled=false;}});
  return {page(){return '<section class="page-heading"><div><p class="overline">OPERAÇÃO HELPU</p><h1>Planos com entrega e margem.</h1><p>Estruture a oferta, confira custos e capacidade e compare cenários antes de contratar.</p></div></section><div id="pricing-workspace"></div>';},mount(view){if(view!=='pricing'){active=false;++sequence;return;}active=true;org=getState()?.company.id||'';data=null;if(!getBoot()?.operator){document.querySelector('#pricing-workspace').innerHTML='<p>Acesso restrito à equipe autorizada.</p>';return;}paint();load();}};
}
